\begin{equation}
\label{equation-isomorphisms-pairs}
\mathit{Isom}_S((\mathcal{L}, \alpha), (\mathcal{L}', \alpha'))
=
\left\{
\begin{matrix}
\emptyset & \text{if} & \text{they are not isomorphic} \\
H^0(S, \mu_{n, S})\cdot \varphi & \text{if} &
\varphi \text{ isomorphism of pairs}
\end{matrix}
\right.
\end{equation}
